using UnityEngine;
namespace Blocklands {public partial class Sandbox
{
    HomePartyPropView partyRide;Transform partyRidePivot;Vector3 partyRideEntry;bool partyRideFlying;float partyRideAge;
    public bool PartyRideActive=>partyRide!=null;public Vector3 PartyRideSavePosition=>partyRideEntry;public bool PartyRideSaveFlying=>partyRideFlying;
    void BuildPortableSwing(Transform root,RoyalArt a){Color pink=new Color(.93f,.62f,.79f),cream=new Color(.94f,.86f,.7f);foreach(float x in new[]{-1.15f,1.15f})a.Piece("便携秋千支柱",new Vector3(x,1.7f,0),new Vector3(.18f,3.4f,.18f),pink,PrimitiveType.Cube,true);a.Piece("便携秋千横梁",new Vector3(0,3.3f,0),new Vector3(2.7f,.2f,.25f),pink);var pivot=new GameObject("PortableSwingPivot").transform;pivot.SetParent(root,false);pivot.localPosition=Vector3.up*3.2f;var ropes=pivot.gameObject.AddComponent<RoyalArt>();foreach(float x in new[]{-.6f,.6f})ropes.Piece("便携秋千绳",new Vector3(x,-1.2f,0),new Vector3(.04f,2.4f,.04f),cream);ropes.Piece("便携秋千座板",new Vector3(0,-2.4f,0),new Vector3(1.6f,.16f,.65f),pink,PrimitiveType.Cube,true);ropes.Piece("秋千柔软坐垫",new Vector3(0,-2.25f,0),new Vector3(1.5f,.4f,.65f),pink,PrimitiveType.Sphere,true);}
    void BuildPortableSlide(Transform root,RoyalArt a){Color blue=new Color(.4f,.67f,.9f),pink=new Color(.94f,.58f,.75f);for(int i=0;i<5;i++)a.Piece("便携滑梯台阶",new Vector3(0,.2f+i*.4f,-1.65f+i*.17f),new Vector3(1.3f,.2f,.38f),blue,PrimitiveType.Cube,true);a.Piece("便携滑梯平台",new Vector3(0,2.2f,-1.2f),new Vector3(1.4f,.18f,.55f),blue,PrimitiveType.Cube,true);var slope=a.Piece("彩色小滑道",new Vector3(0,1.2f,.25f),new Vector3(1.25f,.15f,3.7f),pink,PrimitiveType.Cube,true);slope.localRotation=Quaternion.Euler(35,0,0);foreach(float x in new[]{-.72f,.72f}){var rail=a.Piece("滑梯两侧扶栏",new Vector3(x,1.5f,.25f),new Vector3(.09f,.28f,3.7f),blue);rail.localRotation=slope.localRotation;}}
    public bool StartPartyRide(HomePartyPropView view){if(view==null||view.Data.kind<5||view.Data.kind>6||Paused||CompanionReturnBlocked||Vector3.Distance(Player.transform.position,view.transform.position)>6)return false;PutAwayPartyItem();partyRideEntry=Player.transform.position;partyRideFlying=Player.Flying;partyRide=view;partyRidePivot=view.transform.Find("PortableSwingPivot");partyRideAge=0;Player.SetFlying(false);Player.BeginCoasterSeat();Player.HomeRest(true);Player.transform.rotation=Quaternion.Euler(0,view.Data.yaw,0);TickPartyRide(0);Notice=view.Data.kind==5?"坐上粉色秋千，荡20秒；G提前下来。":"坐上彩色滑梯，滑4秒；G提前下来。";return true;}
    public void TickPartyRide(float dt){if(partyRide==null||Paused)return;partyRideAge+=dt;if(partyRide.Data.kind==5){partyRidePivot.localRotation=Quaternion.Euler(Mathf.Sin(partyRideAge*1.8f)*18,0,0);Player.MoveCoasterSeat(partyRidePivot.TransformPoint(new Vector3(0,-2.3f,0)));if(partyRideAge>=20)StopPartyRide();}else{float t=Mathf.Clamp01(partyRideAge/4);Player.MoveCoasterSeat(partyRide.transform.TransformPoint(new Vector3(0,Mathf.Lerp(2.3f,.2f,t),Mathf.Lerp(-1.25f,1.6f,t))));if(t>=1)StopPartyRide();}}
    public void StopPartyRide(){if(partyRide==null)return;if(partyRidePivot!=null)partyRidePivot.localRotation=Quaternion.identity;Player.MoveCoasterSeat(partyRideEntry);Player.ReleaseCoasterSeat();Player.HomeRest(false);Player.SetFlying(partyRideFlying);partyRide=null;partyRidePivot=null;Notice="已安全下来，用品仍摆在原处；左键可以收回书包。";}
    public bool TryPortableRideG(){if(PartyRideActive){StopPartyRide();return true;}if(Paused||PhoneOpen||!RayFromView(out var hit,5))return false;var view=hit.collider.GetComponentInParent<HomePartyPropView>();return view!=null&&view.Data.kind>=5&&StartPartyRide(view);}
}}
